INSERT INTO sentence_translations (id, sentence_id, lang, text, source) VALUES
  ('st-ex-taritari-1', 'sent-ex-taritari-1', 'en', 'On Sundays I read books, listen to music, and so on.', 'authored'),
  ('st-ex-taritari-2', 'sent-ex-taritari-2', 'en', 'On my day off I clean, do the shopping, and the like.', 'authored'),
  ('st-ex-taritari-3', 'sent-ex-taritari-3', 'en', 'We walked and ran around in the park.', 'authored'),
  ('st-ex-taritari-4', 'sent-ex-taritari-4', 'en', 'Children cry and laugh and cry again.', 'authored'),
  ('st-ex-kotodekiru-1', 'sent-ex-kotodekiru-1', 'en', 'I can play the piano.', 'authored'),
  ('st-ex-kotodekiru-2', 'sent-ex-kotodekiru-2', 'en', 'Can you take photographs at the station?', 'authored'),
  ('st-ex-kotodekiru-3', 'sent-ex-kotodekiru-3', 'en', 'I can''t write difficult kanji.', 'authored'),
  ('st-ex-kotodekiru-4', 'sent-ex-kotodekiru-4', 'en', 'My older brother can drive a car.', 'authored'),
  ('st-ex-kotogaaru-1', 'sent-ex-kotogaaru-1', 'en', 'There are times when I skip breakfast.', 'authored'),
  ('st-ex-kotogaaru-2', 'sent-ex-kotogaaru-2', 'en', 'There are times when I am late for work.', 'authored'),
  ('st-ex-kotogaaru-3', 'sent-ex-kotogaaru-3', 'en', 'There are times when the trains stop because of snow.', 'authored'),
  ('st-ex-kotogaaru-4', 'sent-ex-kotogaaru-4', 'en', 'There are times when I work late into the night.', 'authored'),
  ('st-ex-yotei-1', 'sent-ex-yotei-1', 'en', 'I am planning to go to Japan tomorrow.', 'authored'),
  ('st-ex-yotei-2', 'sent-ex-yotei-2', 'en', 'We are scheduled to hold a meeting next week.', 'authored'),
  ('st-ex-yotei-3', 'sent-ex-yotei-3', 'en', 'Do you have any travel plans?', 'authored'),
  ('st-ex-yotei-4', 'sent-ex-yotei-4', 'en', 'My older brother is planning to get married next year.', 'authored'),
  ('st-ex-souhear-1', 'sent-ex-souhear-1', 'en', 'I hear it will rain tomorrow.', 'authored'),
  ('st-ex-souhear-2', 'sent-ex-souhear-2', 'en', 'They say that shop is cheap.', 'authored'),
  ('st-ex-souhear-3', 'sent-ex-souhear-3', 'en', 'I hear the teacher is not coming.', 'authored'),
  ('st-ex-souhear-4', 'sent-ex-souhear-4', 'en', 'I hear my older brother is well.', 'authored'),
  ('st-ex-souapp-1', 'sent-ex-souapp-1', 'en', 'It looks like it is going to rain.', 'authored'),
  ('st-ex-souapp-2', 'sent-ex-souapp-2', 'en', 'That cake looks delicious.', 'authored'),
  ('st-ex-souapp-3', 'sent-ex-souapp-3', 'en', 'You look well.', 'authored'),
  ('st-ex-souapp-4', 'sent-ex-souapp-4', 'en', 'She looks about to burst into tears.', 'authored'),
  ('st-ex-youda-1', 'sent-ex-youda-1', 'en', 'It seems it rained.', 'authored'),
  ('st-ex-youda-2', 'sent-ex-youda-2', 'en', 'The teacher seems to be busy.', 'authored'),
  ('st-ex-youda-3', 'sent-ex-youda-3', 'en', 'My older brother seems to be tired.', 'authored'),
  ('st-ex-youda-4', 'sent-ex-youda-4', 'en', 'The shop appears to be closed.', 'authored'),
  ('st-ex-rashii-1', 'sent-ex-rashii-1', 'en', 'It seems it will be cold tomorrow.', 'authored'),
  ('st-ex-rashii-2', 'sent-ex-rashii-2', 'en', 'That shop is apparently famous.', 'authored'),
  ('st-ex-rashii-3', 'sent-ex-rashii-3', 'en', 'Apparently my older brother is going to Japan next week.', 'authored'),
  ('st-ex-rashii-4', 'sent-ex-rashii-4', 'en', 'The exam is supposed to be difficult.', 'authored'),
  ('st-ex-mitai-1', 'sent-ex-mitai-1', 'en', 'It looks cold outside.', 'authored'),
  ('st-ex-mitai-2', 'sent-ex-mitai-2', 'en', 'It looks like somebody is in.', 'authored'),
  ('st-ex-mitai-3', 'sent-ex-mitai-3', 'en', 'You are just like a child.', 'authored'),
  ('st-ex-mitai-4', 'sent-ex-mitai-4', 'en', 'That person looks like a teacher.', 'authored'),
  ('st-ex-hazu-1', 'sent-ex-hazu-1', 'en', 'The teacher should have arrived already.', 'authored'),
  ('st-ex-hazu-2', 'sent-ex-hazu-2', 'en', 'The meeting ought to be finishing soon.', 'authored'),
  ('st-ex-hazu-3', 'sent-ex-hazu-3', 'en', 'That shop is supposed to be closed today.', 'authored'),
  ('st-ex-hazu-4', 'sent-ex-hazu-4', 'en', 'My older brother should be able to speak English.', 'authored')
